import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync}from'node:fs';import {gzipSync,gunzipSync}from'node:zlib';
import {activePhysicsTrace,withPhysicsTrace}from'../src/physics/passive-trace.js';
import {measurePinAdjustment}from'../src/dev/pin-adjustment-measurement.js';import {withS7Observation}from'../src/dev/s7-launch-observation.js';
import {contactChange,nearestMotion,envelopeCrossings,createFeedCollector,withFeedDiagnosis,compareFeedOracle}from'../src/dev/s8-feed-diagnosis.js';
import {parseFeedArgs,historicalFiles,loadFeedOracle,feedInputs,validateHistoricalReceipt}from'../tools/s8-feed-diagnosis.mjs';import{createHash}from'node:crypto';
const config=JSON.parse(readFileSync(new URL('../tools/s8-approach-cases.json',import.meta.url))).cases.find(c=>c.id==='three-base');
const point=(id,x,y,vx=0,vy=1)=>({id,x,y,vx,vy,r:1.8,front:true,dead:false});
const short=()=>{const {result,rows}=withS7Observation(()=>measurePinAdjustment(config,{seconds:2,drain:1,replaySeconds:3,replayFPS:30}),{phase:0});result.s8ShotObservation={rows:result.events.filter(e=>e.type==='shot').map(e=>rows.get(e.ballId))};return result;};
function fakeResult(ids,successful=[]){return {physical:{shots:ids.length},events:ids.flatMap(ballId=>[{type:'shot',ballId,time:0},{type:'outcome',ballId,kind:'out',time:2}]),s8ShotObservation:{rows:ids.map(ballId=>({ballId,firstWindmillContact:successful.includes(ballId)?{}:null,route:{firstDescending:null}}))},end:{time:2}};}
test('short real trace OFF/ON all saved fields exact; compressed historical representation and observer restoration',()=>{
 const plain=short(),rows=[],observed=withFeedDiagnosis(short,e=>rows.push(e));assert.deepEqual(observed.result,plain);const old=JSON.parse(gunzipSync(gzipSync(JSON.stringify(plain))));assert.equal(compareFeedOracle(observed.result,old).exact,true);assert.ok(rows.some(e=>e.type==='contact'&&e.part.kind==='pin')||rows.some(e=>e.type==='motion'));assert.equal(activePhysicsTrace,null);assert.throws(()=>withFeedDiagnosis(()=>{throw Error('original');}),/original/);assert.equal(activePhysicsTrace,null);
 for(const k of ['configSHA','layoutSHA','flowOptions','events'])assert.equal(compareFeedOracle({...plain,[k]:'changed'},old).exact,false);assert.equal(compareFeedOracle({...plain,sourceSHA:'new',planSHA:'new',caseManifestSHA:'new'},old).exact,true);
});
test('copied diagnostic sink mutation cannot change physics, and failure restores passive hook',()=>{
 const plain=short(),observed=withFeedDiagnosis(short,e=>{if(e.before)e.before.x=1e9;if(e.part)e.part.id=-1;});assert.deepEqual(observed.result,plain);assert.throws(()=>withFeedDiagnosis(short,()=>{throw Error('write failed');}),/write failed/);assert.equal(activePhysicsTrace,null);
});
test('position-only, velocity-only and both contacts retain repeated IDs/order and explicit250/70/180 denominator',()=>{
 assert.equal(contactChange(point(1,0,0),point(1,1,0)),'position-only');assert.equal(contactChange(point(1,0,0),point(1,0,0,2)),'velocity-only');assert.equal(contactChange(point(1,0,0),point(1,1,0,2)),'both');const saved=[],c=createFeedCollector(e=>saved.push(e));
 for(let id=1;id<=250;id++){if(id<=70)c.accept({type:'contact',time:1,stage:'wheel',part:{kind:'windmill-photo-three-vane'},before:point(id,65,476),after:point(id,66,476,2),solverResult:1});else if(id<=80)c.accept({type:'contact',time:1,stage:'wheel',part:{kind:'windmill-photo-three-vane'},before:point(id,65,476),after:point(id,66,476),solverResult:0});c.accept({type:'outcome',time:2,outcome:'out',ball:point(id,0,700)});}
 const summary=c.finish(fakeResult(Array.from({length:250},(_,i)=>i+1),Array.from({length:70},(_,i)=>i+1)));assert.deepEqual(summary.counts,{shots:250,successfulWindmill:70,noSuccessfulWindmill:180,positionOnlyWindmill:10,changedWindmill:80,noChangedWindmill:170,velocityChangingWindmill:70,frontChangedWindmill:80,frontSuccessfulWindmill:70,backOrTransitionWindmill:0});assert.equal(saved.filter(e=>e.type==='endpoint').length,250);assert.ok(saved.every((e,i)=>e.seq===i+1));assert.throws(()=>c.finish(fakeResult([1])),/unknown ball/);
 const d=createFeedCollector();for(const time of [.5,.6])d.accept({type:'contact',time,stage:'pin',part:{kind:'pin',id:54},before:point(1,69,447),after:point(1,68,447,-2),solverResult:true});d.accept({type:'contact',time:.7,stage:'pin',part:{kind:'pin',id:63},before:point(1,60,457),after:point(1,61,457),solverResult:false});d.accept({type:'contact',time:1,stage:'wheel',part:{kind:'windmill-photo-three-vane'},before:point(1,65,476),after:point(1,66,476,2),solverResult:1});d.accept({type:'outcome',time:2,outcome:'out',ball:point(1,0,700)});const row=d.finish(fakeResult([1],[1])).balls[0];assert.equal(row.pinContacts.length,3);assert.equal(row.windmillContacts[0].precedingApproachContact.time,.7);assert.equal(row.windmillContacts[0].precedingApproachReflection.time,.6);
});
test('actual point minimum differs from motion-segment minimum; correction has no fabricated motion crossing',()=>{
 const before=point(1,50,476.5),after=point(1,78,476.5),n=nearestMotion(before,after);assert.equal(n.distance,0);assert.equal(n.fraction,.5);assert.deepEqual(envelopeCrossings(before,after,10).map(e=>e.direction),['enter','exit']);const saved=[],c=createFeedCollector(e=>saved.push(e));c.accept({type:'motion',time:1,timeStart:.9,timeEnd:1,gameTime:.8,before,after});c.accept({type:'outcome',time:2,outcome:'out',ball:point(1,0,700)});const row=c.finish(fakeResult([1])).balls[0];assert.equal(row.pointMinimum.distance,14);assert.equal(row.motionMinimum.distance,0);assert.equal(saved.filter(e=>e.type==='envelope-cross').length,4);
 const corrected=[],d=createFeedCollector(e=>corrected.push(e));d.accept({type:'contact',time:1,stage:'pin',part:{kind:'pin',id:54},before,after,solverResult:false});d.accept({type:'outcome',time:2,outcome:'out',ball:point(1,0,700)});const dr=d.finish(fakeResult([1])).balls[0];assert.equal(dr.motionMinimum,null);assert.equal(corrected.some(e=>e.type==='envelope-cross'),false);
 const back=createFeedCollector();back.accept({type:'motion',time:1,timeStart:.9,timeEnd:1,before:{...before,front:false},after:{...after,front:false}});back.accept({type:'outcome',time:2,outcome:'out',ball:{...point(1,0,700),front:false}});const b=back.finish(fakeResult([1])).balls[0];assert.equal(b.pointMinimum,null);assert.equal(b.motionMinimum,null);
});
test('runner strictly allows one explicit phase0 baseline, complete safe source paths and source freeze',()=>{
 const args=['--out','out','--plan','plan','--manifest','manifest','--oracle','oracle','--phase','0','--stage','preflight'];assert.equal(parseFeedArgs(args)['--stage'],'preflight');assert.throws(()=>parseFeedArgs([...args,'--case','other']),/Unknown/);assert.throws(()=>parseFeedArgs(args.map(x=>x==='preflight'?'run':x)),/Frozen/);assert.throws(()=>parseFeedArgs(args.map(x=>x==='0'?'.175':x)),/phase0/);assert.throws(()=>historicalFiles({files:[{path:'../bad',sha256:'a'.repeat(64)}]}),/Unsafe/);assert.throws(()=>historicalFiles({files:[{path:'prototype/x',sha256:'a'.repeat(64)},{path:'prototype/x',sha256:'b'.repeat(64)}]}),/Conflicting/);
});
test('historical receipt checks both raw hashes/bytes, HEAD, config/layout, plan and frame coverage',()=>{
 const sha=x=>createHash('sha256').update(x).digest('hex'),compressed=Buffer.from('gzip bytes'),expanded=Buffer.from('JSON bytes'),plan=Buffer.from('plan'),cases=Buffer.from('cases'),h={sourceSHA:'a',configSHA:'b',layoutSHA:'c',planSHA:sha(plan),caseManifestSHA:sha(cases),phase:0,conditions:{mode:'normal'},physical:{shots:250},replayFPS:30,replayFrames:[{}]},p={success:true,sourceUnchanged:true,gitUnchanged:true,commit:'head',endCommit:'head',source:{sha256:'a',planSHA:sha(plan),caseManifestSHA:sha(cases)},endSourceSHA:'a',caseId:'three-base',phase:0,mode:'normal'},r={file:'result.json.gz',sourceSHA:'a',configSHA:'b',layoutSHA:'c',compressedSHA:sha(compressed),expandedSHA:sha(expanded),compressedBytes:compressed.length,expandedBytes:expanded.length,replayFPS:30,frames:1};assert.equal(validateHistoricalReceipt(h,p,r,compressed,expanded,plan,cases),true);for(const bad of [{...r,expandedBytes:0},{...r,compressedSHA:'bad'},{...r,configSHA:'bad'},{...r,layoutSHA:'bad'},{...r,frames:2}])assert.throws(()=>validateHistoricalReceipt(h,p,bad,compressed,expanded,plan,cases),/mismatch/);assert.throws(()=>validateHistoricalReceipt(h,{...p,endCommit:'other'},r,compressed,expanded,plan,cases),/mismatch/);assert.throws(()=>validateHistoricalReceipt(h,p,r,compressed,expanded,Buffer.from('changed'),cases),/mismatch/);
});
